theorem numbertheory_notEquiv2i2jasqbsqdiv8 :
  ¬ (∀ a b : ℤ, (∃ i j, a = 2*i ∧ b=2*j) ↔ (∃ k, a^2 + b^2 = 8*k)) := by
  intro h
  have h₁ := h 2 2
  have h₂ := h 2 0
  have h₃ := h 0 2
  have h₄ := h 0 0
  simp at h₁ h₂ h₃ h₄
  <;>
  (try contradiction) <;>
  (try {
    rcases h₁ with ⟨i, j, hi, hj⟩
    rcases h₂ with ⟨k₁, hk₁⟩
    rcases h₃ with ⟨k₂, hk₂⟩
    rcases h₄ with ⟨k₃, hk₃⟩
    norm_num at hi hj hk₁ hk₂ hk₃
    <;>
    (try {
      linarith
    }) <;>
    (try {
      contradiction
    })
  }) <;>
  (try {
    rcases h₁ with ⟨i, j, hi, hj⟩
    rcases h₂ with ⟨k₁, hk₁⟩
    rcases h₃ with ⟨k₂, hk₂⟩
    rcases h₄ with ⟨k₃, hk₃⟩
    norm_num at hi hj hk₁ hk₂ hk₃
    <;>
    (try {
      linarith
    }) <;>
    (try {
      contradiction
    })
  })
